// v0.5 polish: layered gear has its own repair target and wears when it absorbs danger.
const irV05RepairBase=ir04Repair;
ir04Repair=function(slot){
 const c=state?.character;
 if(!c)return;
 if(['head','hands','legs','feet'].includes(slot)){
  const id=c.equipment?.[slot];
  if(!id||!IR_V05_GEAR[id]){toast('There is no layered armor equipped in that slot.');return}
  const cond=Number(c.itemCondition?.[id]??100);
  if(cond>=100){toast('This equipment is already in good condition.');return}
  const currentSite=site();
  if(!(currentSite.services||[]).some(x=>['forge','workshop','smithy'].includes(x))){toast('Travel to a settlement with a forge or workshop to repair layered armor.');return}
  const fee=Math.max(3,Math.ceil((IR_V04_ITEM_DATA[id]?.value||ITEMS[id]?.sell||10)*(100-cond)/180));
  if(c.coin<fee){toast(`Repair costs ${fee} coins.`);return}
  c.coin-=fee;c.itemCondition[id]=100;c.professionStats.repairs++;gainSkill('Smithing',8);ir04AwardXP(4,'layered equipment repair');
  addFeed('🛠️','Layered armor repaired',`${ITEMS[id]?.name||id} was restored to full condition for ${coins(fee)}.`);persist();render();toast('Layered armor repaired.');return;
 }
 return irV05RepairBase(slot);
};
const irV05BattleMoveWearBase=irBattleMove;
irBattleMove=function(move,itemId){
 const c=state?.character,beforeHP=c?.health;
 const layers=c?['head','hands','legs','feet'].map(slot=>({slot,id:c.equipment?.[slot]})).filter(x=>x.id):[];
 irV05BattleMoveWearBase(move,itemId);
 if(c&&state?.character===c&&Number(beforeHP)>Number(c.health)){
  let changed=false;
  for(const x of layers){if(c.itemCondition?.[x.id]!==undefined){const old=c.itemCondition[x.id];c.itemCondition[x.id]=Math.max(0,old-1);changed=changed||c.itemCondition[x.id]!==old;}}
  if(changed){persist();render();}
 }
};
